action.script:

import com.liferay.commerce.constants.CommerceOrderConstants;
import com.liferay.commerce.model.CommerceOrder;
import com.liferay.commerce.service.CommerceOrderLocalServiceUtil;
import com.liferay.object.service.ObjectEntryLocalServiceUtil;
import com.liferay.portal.kernel.util.GetterUtil;
import com.liferay.portal.kernel.workflow.WorkflowConstants;
import com.liferay.portal.kernel.workflow.WorkflowStatusManagerUtil;

import java.math.BigDecimal;

Map<String, Serializable> objectEntryValues = ObjectEntryLocalServiceUtil.getValues(kaleoInstanceToken.getClassPK());

int billingOption = GetterUtil.getInteger(objectEntryValues.get("billingOption"));

BigDecimal finalPrice = 0.0;

Map<String, Serializable> quoteComparisonEntryValues = ObjectEntryLocalServiceUtil.getValues(GetterUtil.getLong(objectEntryValues.get("r_quoteComparisonToRaylifeOrders_c_quoteComparisonId")));

if (billingOption == 1) {
	finalPrice = GetterUtil.getNumber(quoteComparisonEntryValues.get("promo"));
} else if (billingOption == 2) {
	finalPrice = GetterUtil.getNumber(quoteComparisonEntryValues.get("price")) / 2;;
}

CommerceOrder commerceOrder = CommerceOrderLocalServiceUtil.getCommerceOrder(GetterUtil.getLong(objectEntryValues.get("r_commerceOrderToRaylifeOrders_commerceOrderId")));

commerceOrder.setTotal(finalPrice);
commerceOrder.setSubtotal(finalPrice);

CommerceOrderLocalServiceUtil.updateCommerceOrder(commerceOrder);

WorkflowStatusManagerUtil.updateStatus(WorkflowConstants.getLabelStatus("approved"), workflowContext);
